43	/// When no compiled-in line claims the config but the identity belongs to a
44	/// known family, tell the user which feature to rebuild with.
45	///
46	/// The identity strings here must stay in sync with each line's `probe`
47	/// gate: this table exists precisely because the line (and its probe) is
48	/// compiled out, so the duplication cannot be derived away.
49	fn feature_gate_hint(config: &serde_json::Value) -> Option<String> {
50	    struct Family {
51	        feature: &'static str,
52	        model_types: &'static [&'static str],
53	        text_model_types: &'static [&'static str],
54	        compiled: bool,
55	    }
56	    let model_type = config
57	        .get("model_type")
58	        .and_then(serde_json::Value::as_str)
59	        .unwrap_or("");
60	    let text_model_type = config
61	        .get("text_config")
62	        .and_then(|text| text.get("model_type"))
63	        .and_then(serde_json::Value::as_str)
64	        .unwrap_or("");
65	    let families = [
66	        Family {
67	            feature: "deepseek-v2-lite",
68	            model_types: &["deepseek_v2"],
69	            text_model_types: &[],
70	            compiled: cfg!(feature = "deepseek-v2-lite"),
71	        },
72	        Family {
73	            feature: "gemma4",
74	            model_types: &["gemma4", "gemma4_unified"],
75	            text_model_types: &["gemma4_text", "gemma4_unified_text"],
76	            compiled: cfg!(feature = "gemma4"),
77	        },
78	        Family {
79	            feature: "glm52",
80	            model_types: &["glm_moe_dsa"],
81	            text_model_types: &[],
82	            compiled: cfg!(feature = "glm52"),
83	        },
84	        Family {
85	            feature: "k3",
86	            model_types: &["kimi_k3"],
87	            text_model_types: &["kimi_linear"],
88	            compiled: cfg!(feature = "k3"),
89	        },
90	        Family {
91	            feature: "kimi-k2",
92	            model_types: &["kimi_k25", "kimi_k2"],
93	            text_model_types: &["kimi_k2"],
94	            compiled: cfg!(feature = "kimi-k2"),
95	        },
96	        Family {
97	            feature: "qwen3",
98	            model_types: &["qwen3"],
99	            text_model_types: &[],
100	            compiled: cfg!(feature = "qwen3"),
101	        },
102	        Family {
103	            feature: "qwen35",
104	            model_types: &["qwen3_5"],
105	            text_model_types: &["qwen3_5_text"],
106	            compiled: cfg!(feature = "qwen35"),
107	        },
108	    ];
109	    families.iter().find_map(|family| {
110	        (!family.compiled
111	            && (family.model_types.contains(&model_type)
112	                || family.text_model_types.contains(&text_model_type)))
113	        .then(|| {
114	            format!(
115	                "this looks like a {} model; rebuild pegainfer-server with --features {}",
116	                family.feature, family.feature
117	            )
118	        })
119	    })
120	}
