122	#[tokio::main]
123	async fn main() -> anyhow::Result<()> {
124	    logging::init_default();
125	    pegainfer_core::tracing::init();
126	
127	    let registry = ModelLineRegistry::new(model_lines());
128	    let cmd = registry.build_command(
129	        clap::Command::new("pegainfer")
130	            .version(env!("CARGO_PKG_VERSION"))
131	            .about("PegaInfer GPU inference server"),
132	    );
133	    let matches = cmd.clone().get_matches();
134	    let shared = SharedArgs::from_arg_matches(&matches)
135	        .map_err(|error| anyhow::anyhow!("invalid CLI args: {error}"))?;
136	    let provided = provided_args(&matches, &cmd);
137	
138	    let config_path = shared.model_path.join("config.json");
139	    let content = std::fs::read_to_string(&config_path)
140	        .with_context(|| format!("failed to read {}", config_path.display()))?;
141	    let config: serde_json::Value = serde_json::from_str(&content)
142	        .with_context(|| format!("failed to parse {}", config_path.display()))?;
143	
144	    let line = registry.detect(&config).map_err(|error| {
145	        if matches!(error, DetectError::NoMatch { .. }) {
146	            if let Some(hint) = feature_gate_hint(&config) {
147	                return anyhow::anyhow!("{error}; {hint}");
148	            }
149	        }
150	        anyhow::Error::from(error)
151	    })?;
152	
153	    registry.validate_provided(line, &provided, &cmd)?;
154	    shared.validate(&provided)?;
155	    let ctx = LaunchContext {
156	        model_path: &shared.model_path,
157	        config: &config,
158	        shared: &shared,
159	        matches: &matches,
160	    };
161	    line.validate(&ctx, &provided)?;
162	    let plan = line.serve_plan(&ctx)?;
163	
164	    info!("=== pegainfer - {} (GPU) ===", line.name());
165	    info!("Loading engine...");
166	    let start = Instant::now();
167	    info!(
168	        "Runtime: model_path={}, user-set flags {provided:?}",
169	        shared.model_path.display(),
170	    );
171	
172	    let model_path = shared.model_path.clone();
173	    let served_model_name = shared.served_model_name.clone();
174	    let port = shared.port;
175	
176	    // Engine load (weights → GPU) runs on a blocking thread so the HTTP
177	    // frontend (tokenizer, chat templates) loads concurrently. The frontend
178	    // binds only after the engine registers, so readiness is unchanged.
179	    let engine_load = tokio::task::spawn_blocking(move || -> anyhow::Result<LaunchedEngine> {
180	        let ctx = LaunchContext {
181	            model_path: &shared.model_path,
182	            config: &config,
183	            shared: &shared,
184	            matches: &matches,
185	        };
186	        line.launch(&ctx)
187	            .with_context(|| format!("failed to start {} engine", line.name()))
188	    });
189	
190	    let serve_result = if let Some(lora_modules) = plan.lora_modules {
191	        // LoRA routes need the engine's control plane when the router is
192	        // built, so this path stays sequential.
193	        let launched = engine_load
194	            .await
195	            .context("engine loader thread panicked")??;
196	        let LaunchedEngine::Stepped(engine) = launched else {
197	            anyhow::bail!("LoRA serving requires a step-driven engine");
198	        };
199	        info!("Engine loaded: elapsed_ms={}", start.elapsed().as_millis());
200	        let max_model_len =
201	            pegainfer_frontend::vllm::load_max_model_len(&model_path).unwrap_or(4096);
202	        pegainfer_frontend::vllm::serve_model_with_lora_routes(
203	            engine,
204	            model_path.to_string_lossy().into_owned(),
205	            served_model_name.into_iter().collect(),
206	            lora_modules,
207	            port,
208	            max_model_len,
209	            pegainfer_frontend::vllm::shutdown_token_from_ctrl_c(),
210	        )
211	        .await
212	    } else {
213	        let shutdown = tokio_util::sync::CancellationToken::new();
214	        let engine = {
215	            let shutdown = shutdown.clone();
216	            async move {
217	                let handle = engine_load
218	                    .await
219	                    .context("engine loader thread panicked")??;
220	                info!("Engine loaded: elapsed_ms={}", start.elapsed().as_millis());
221	                // The blocking load can't be cancelled, so SIGINT keeps its
222	                // default kill behavior until the engine is up; only then
223	                // switch to graceful shutdown.
224	                pegainfer_frontend::vllm::cancel_token_on_ctrl_c(&shutdown);
225	                anyhow::Ok(handle)
226	            }
227	        };
228	        if plan.prefill_only {
229	            pegainfer_frontend::vllm::serve_prefill_only_with_engine_count(
230	                engine,
231	                &model_path,
232	                served_model_name.into_iter().collect(),
233	                port,
234	                None,
235	                plan.scheduler_partition_count,
236	                shutdown,
237	            )
238	            .await
239	        } else {
240	            pegainfer_frontend::vllm::serve_with_engine_count(
241	                engine,
242	                &model_path,
243	                served_model_name.into_iter().collect(),
244	                port,
245	                None,
246	                plan.scheduler_partition_count,
247	                shutdown,
248	            )
249	            .await
250	        }
251	    }
252	    .context("vLLM frontend server failed");
253	
254	    // Export the final batch of request spans before the runtime tears down.
255	    // Flush before propagating an error too — a failed server is exactly where
256	    // the last buffered spans matter. No-op when tracing was never enabled.
257	    pegainfer_core::tracing::flush();
258	    serve_result?;
259	
260	    Ok(())
261	}
