74	/// Shared CLI selector for model lines that can overlap prefill and decode.
75	#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, clap::ValueEnum)]
76	pub enum CliDecodeOverlap {
77	    /// One stream; prefill and decode serialize.
78	    #[default]
79	    Off,
80	    /// Two CUDA streams sharing all SMs.
81	    Stream,
82	    /// Green Context SM partition (SM-pinned streams).
83	    #[value(name = "green-ctx")]
84	    GreenCtx,
85	}
