148	    pub kv_offload_host_gib: f64,
149	
150	    /// Back the KV offload pool with 2 MiB hugepages. The box must hold a
151	    /// reservation covering the pool (`HugePages_Total` in /proc/meminfo;
152	    /// `echo N > /proc/sys/vm/nr_hugepages` as root) — allocation fails at
153	    /// startup otherwise.
154	    #[arg(long, default_value_t = false)]
155	    pub kv_offload_hugepages: bool,
