219	impl SharedArgs {
220	    /// Interactions between shared flags that hold for every consumer.
221	    /// Line-specific rules live in each line's [`ModelLine::validate`].
222	    pub fn validate(&self, provided: &BTreeSet<String>) -> Result<(), CliError> {
223	        if self.dump_graph_png.is_some() && !self.cuda_graph {
224	            return Err(CliError::rule(
225	                "--dump-graph-png requires --cuda-graph=true",
226	            ));
227	        }
228	        if provided.contains("device_ordinal") && self.tp_size > 1 {
229	            return Err(CliError::rule(
230	                "--device-ordinal is ignored under tensor parallelism; tp_size>1 uses devices 0..tp_size",
231	            ));
232	        }
233	        if provided.contains("decode_sm_pct") && self.decode_overlap != CliDecodeOverlap::GreenCtx {
234	            return Err(CliError::rule(
235	                "--decode-sm-pct only applies with --decode-overlap=green-ctx",
236	            ));
237	        }
238	        Ok(())
239	    }
