360	#[derive(Default)]
361	struct RegistryClaims {
362	    ids: BTreeMap<String, ArgOwner>,
363	    spellings: BTreeMap<String, ArgOwner>,
364	}
365	
366	impl RegistryClaims {
367	    fn register_command(&mut self, command: &clap::Command, owner: ArgOwner) -> BTreeSet<String> {
368	        command
369	            .get_arguments()
370	            .map(|arg| self.register_arg(arg, owner))
371	            .collect()
372	    }
373	
374	    fn register_arg(&mut self, arg: &clap::Arg, owner: ArgOwner) -> String {
375	        let id = arg.get_id().to_string();
376	        self.claim_id(id.clone(), owner);
377	        for long in arg
378	            .get_long()
379	            .into_iter()
380	            .chain(arg.get_all_aliases().into_iter().flatten())
381	        {
382	            self.claim_spelling(format!("--{long}"), owner);
383	        }
384	        for short in arg
385	            .get_short()
386	            .into_iter()
387	            .chain(arg.get_all_short_aliases().into_iter().flatten())
388	        {
389	            self.claim_spelling(format!("-{short}"), owner);
390	        }
391	        id
392	    }
393	
394	    fn claim_id(&mut self, id: String, owner: ArgOwner) {
395	        if let Some(previous) = self.ids.get(&id) {
396	            if *previous == ArgOwner::Shared {
397	                if let ArgOwner::Line(name) = owner {
398	                    panic!(
399	                        "model line {name} redeclares SharedArgs flag id {id:?}; list it in consumed_shared_args instead"
400	                    );
401	                }
402	            }
403	            panic!("{previous} and {owner} both define flag id {id:?}");
404	        }
405	        self.ids.insert(id, owner);
406	    }
407	
408	    fn claim_spelling(&mut self, spelling: String, owner: ArgOwner) {
409	        if let Some(previous) = self.spellings.get(&spelling) {
410	            panic!("{previous} and {owner} both define CLI spelling {spelling:?}");
411	        }
412	        self.spellings.insert(spelling, owner);
413	    }
414	
415	    fn is_shared_id(&self, id: &str) -> bool {
416	        self.ids.get(id) == Some(&ArgOwner::Shared)
417	    }
418	
419	    fn validate_requirement(&self, owner: ArgOwner, source: &str, targets: &[&str]) {
420	        assert!(
421	            self.ids.get(source) == Some(&owner),
422	            "{owner} declares requirements for unowned flag id {source:?}"
423	        );
424	        for &target in targets {
425	            assert!(source != target, "flag id {source:?} cannot require itself");
426	            let target_owner = self.ids.get(target);
427	            assert!(
428	                target_owner == Some(&ArgOwner::Shared) || target_owner == Some(&owner),
429	                "{owner} flag id {source:?} requires unknown or foreign argument id {target:?}"
430	            );
431	        }
432	    }
433	}
434	
435	fn register_line(
436	    line: &'static dyn ModelLine,
437	    owner: ArgOwner,
438	    claims: &mut RegistryClaims,
439	) -> LineEntry {
440	    for id in line.consumed_shared_args() {
441	        assert!(
442	            claims.is_shared_id(id),
443	            "model line {} consumes unknown SharedArgs flag id {id:?}",
444	            line.name()
445	        );
446	    }
447	    let command = line.augment_cli(clap::Command::new("probe"));
448	    let own_ids = claims.register_command(&command, owner);
449	    LineEntry { line, own_ids }
450	}
