521	    /// Find the unique line that claims this `config.json`. On
522	    /// [`DetectError::NoMatch`] the caller may prepend a hint for families
523	    /// that exist but were compiled out.
524	    pub fn detect(
525	        &self,
526	        config: &serde_json::Value,
527	    ) -> Result<&'static dyn ModelLine, DetectError> {
528	        let mut rejections = Vec::new();
529	        let mut claimed: Option<&'static dyn ModelLine> = None;
530	        for entry in &self.entries {
531	            match entry.line.probe(config) {
532	                Ok(()) => match claimed {
533	                    None => claimed = Some(entry.line),
534	                    Some(prev) => {
535	                        return Err(DetectError::Conflict {
536	                            first: prev.name(),
537	                            second: entry.line.name(),
538	                        });
539	                    }
540	                },
541	                Err(reason) => rejections.push(format!("{}: {reason}", entry.line.name())),
542	            }
543	        }
544	        claimed.ok_or_else(|| {
545	            let render = |key: &str| {
546	                config
547	                    .get(key)
548	                    .map_or_else(|| "missing".to_string(), std::string::ToString::to_string)
549	            };
550	            DetectError::NoMatch {
551	                model_type: render("model_type"),
552	                architectures: render("architectures"),
553	                rejections,
554	            }
555	        })
556	    }
557	
558	    /// Consume-or-reject: every explicitly provided flag must be a core flag,
559	    /// a shared flag the detected line consumes, or one of the line's own.
560	    pub fn validate_provided(
561	        &self,
562	        detected: &'static dyn ModelLine,
563	        provided: &BTreeSet<String>,
564	        cmd: &clap::Command,
565	    ) -> Result<(), CliError> {
566	        let entry = self
567	            .entries
568	            .iter()
569	            .find(|entry| std::ptr::eq(entry.line, detected))
570	            .expect("detected line came from this registry");
571	        for id in provided {
572	            let id = id.as_str();
573	            if CORE_ARGS.contains(&id)
574	                || detected.consumed_shared_args().contains(&id)
575	                || entry.own_ids.contains(id)
576	            {
577	                continue;
578	            }
579	            return Err(CliError::UnconsumedFlag {
580	                flag: long_flag(cmd, id),
581	                line: detected.name(),
582	            });
583	        }
584	        Ok(())
585	    }
586	}
