588	fn long_flag(cmd: &clap::Command, id: &str) -> String {
589	    cmd.get_arguments()
590	        .find(|arg| arg.get_id() == id)
591	        .and_then(clap::Arg::get_long)
592	        .map_or_else(|| id.to_owned(), str::to_owned)
593	}
594	
595	/// Arg ids the user set explicitly (command line or env), for consume-or-reject.
596	pub fn provided_args(matches: &clap::ArgMatches, cmd: &clap::Command) -> BTreeSet<String> {
597	    // matches.ids() also yields clap's synthetic group ids; keep only real args.
598	    let real: BTreeSet<&str> = cmd
599	        .get_arguments()
600	        .map(|arg| arg.get_id().as_str())
601	        .collect();
602	    matches
603	        .ids()
604	        .map(clap::Id::as_str)
605	        .filter(|id| real.contains(id))
606	        .filter(|id| {
607	            matches!(
608	                matches.value_source(id),
609	                Some(
610	                    clap::parser::ValueSource::CommandLine | clap::parser::ValueSource::EnvVariable
611	                )
612	            )
613	        })
614	        .map(str::to_owned)
615	        .collect()
616	}
