56	/// Serve while the engine is still loading: the HTTP frontend (tokenizer,
57	/// chat templates) starts immediately and the engine bridge attaches once
58	/// `engine` resolves. HTTP binds only after the bridge registers, so a
59	/// reachable port still means the engine is ready.
60	///
61	/// Pass `max_model_len: None` to read `max_position_embeddings` from
62	/// `model_path/config.json`; pass `Some(n)` when the path has no config
63	/// (e.g. a HuggingFace model id for the sim frontend).
64	pub async fn serve(
65	    engine: impl Future<Output = Result<LaunchedEngine>> + Send + 'static,
66	    model_path: &Path,
67	    served_model_name: Vec<String>,
68	    port: u16,
69	    max_model_len: Option<u32>,
70	    shutdown: CancellationToken,
71	) -> Result<()> {
72	    serve_with_engine_count(
73	        engine,
74	        model_path,
75	        served_model_name,
76	        port,
77	        max_model_len,
78	        1,
79	        shutdown,
80	    )
81	    .await
82	}
